// Combine health check and AI brief
const health = $input.first().json;
const aiBrief = $input.last().json;

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

return [{
  json: {
    date: today,
    health: health.status || 'unknown',
    aiContent: aiBrief.response || aiBrief.content || 'AI brief unavailable',
    mcpEndpoint: 'https://integratewise-mcp-connector.connect-a1b.workers.dev'
  }
}];

